const esbuild = require("esbuild")
const builtins = require("builtin-modules").default || require("builtin-modules")

const banner = `/*
MUGS — Multi-User Git Sync.
Production bundle (minified). Run "npm run build".
*/`

esbuild
  .build({
    banner: { js: banner },
    entryPoints: ["src/main.ts"],
    bundle: true,
    external: [
      "obsidian",
      "electron",
      "@codemirror/autocomplete",
      "@codemirror/collab",
      "@codemirror/commands",
      "@codemirror/language",
      "@codemirror/lint",
      "@codemirror/search",
      "@codemirror/state",
      "@codemirror/view",
      "@lezer/common",
      "@lezer/highlight",
      "@lezer/lr",
      ...builtins,
    ],
    format: "cjs",
    target: "es2018",
    logLevel: "info",
    sourcemap: false,
    treeShaking: true,
    minify: true,
    outfile: "main.js",
  })
  .then(() => console.log("Build complete (production)"))
  .catch((e) => {
    console.error(e)
    process.exit(1)
  })
